define([],function(){const TAU=Math.PI*2;const EPSILON=1e-12;const SVG_CENTER=250;const SVG_RADIUS=180;const ARC_RADIUS=50;const TANGENT_X=SVG_CENTER+SVG_RADIUS;const toRadians=degrees=>degrees*Math.PI/180;const toDegrees=radians=>radians*180/Math.PI;const normalizeDegrees=value=>{const normalized=value%360;return normalized<0?normalized+360:normalized};const normalizeRadians=value=>{const normalized=value%TAU;return normalized<0?normalized+TAU:normalized};const clean=value=>Math.abs(value)<EPSILON?0:value;const format=(value,precision=10)=>{if(!Number.isFinite(value)){return"-"}const cleaned=clean(value);return String(Number.parseFloat(cleaned.toPrecision(precision)))};const setText=(root,selector,value)=>{const node=root.querySelector(selector);if(node){node.textContent=value}};const pointForAngle=radians=>({x:SVG_CENTER+SVG_RADIUS*Math.cos(radians),y:SVG_CENTER-SVG_RADIUS*Math.sin(radians)});const polarPoint=(radians,radius)=>({x:SVG_CENTER+radius*Math.cos(radians),y:SVG_CENTER-radius*Math.sin(radians)});const buildArc=radians=>{const normalized=normalizeRadians(radians);if(normalized<EPSILON){const start=polarPoint(0,ARC_RADIUS);return`M ${start.x} ${start.y}`}const start=polarPoint(0,ARC_RADIUS);const end=polarPoint(normalized,ARC_RADIUS);const largeArc=normalized>Math.PI?1:0;return`M ${start.x} ${start.y} A ${ARC_RADIUS} ${ARC_RADIUS} 0 ${largeArc} 0 ${end.x} ${end.y}`};const updateCircle=(root,radians,tangentValue,undefinedLabel)=>{const point=pointForAngle(radians);const sin=clean(Math.sin(radians));const cos=clean(Math.cos(radians));const svg=root.querySelector(".trigonometry-circle");const marker=svg.querySelector(".trigonometry-point");const radius=svg.querySelector(".trigonometry-radius");const projectionX=svg.querySelector(".trigonometry-projection-x");const projectionY=svg.querySelector(".trigonometry-projection-y");const arc=svg.querySelector(".trigonometry-angle-arc");const tangent=svg.querySelector(".trigonometry-tangent-segment");const theta=svg.querySelector(".trigonometry-theta-label");marker.setAttribute("cx",point.x);marker.setAttribute("cy",point.y);radius.setAttribute("x2",point.x);radius.setAttribute("y2",point.y);projectionX.setAttribute("x2",point.x);projectionX.setAttribute("y2",SVG_CENTER);projectionY.setAttribute("x1",point.x);projectionY.setAttribute("y1",SVG_CENTER);projectionY.setAttribute("x2",point.x);projectionY.setAttribute("y2",point.y);arc.setAttribute("d",buildArc(radians));const thetaPoint=polarPoint(normalizeRadians(radians)/2,72);theta.setAttribute("x",thetaPoint.x);theta.setAttribute("y",thetaPoint.y);if(Number.isFinite(tangentValue)&&Math.abs(tangentValue)<=1.15){const tangentY=SVG_CENTER-SVG_RADIUS*tangentValue;tangent.setAttribute("x1",TANGENT_X);tangent.setAttribute("y1",SVG_CENTER);tangent.setAttribute("x2",TANGENT_X);tangent.setAttribute("y2",tangentY);tangent.removeAttribute("visibility")}else{tangent.setAttribute("visibility","hidden")}setText(root,'[data-circle="x"]',format(cos,8));setText(root,'[data-circle="y"]',format(sin,8));setText(root,'[data-circle="tan"]',Number.isFinite(tangentValue)?format(tangentValue,8):undefinedLabel)};const calculateAngle=root=>{const input=root.querySelector(".trigonometry-angle");const unit=root.querySelector(".trigonometry-unit").value;const undefinedLabel=root.dataset.undefined;const raw=Number(input.value);if(!Number.isFinite(raw)){["sin","cos","tan","coordinates","normalized"].forEach(key=>{setText(root,`[data-result="${key}"]`,"-")});return}const radians=unit==="degrees"?toRadians(raw):raw;const degrees=toDegrees(radians);const sin=clean(Math.sin(radians));const cos=clean(Math.cos(radians));const tangentDefined=Math.abs(cos)>EPSILON;const tan=tangentDefined?clean(sin/cos):NaN;setText(root,'[data-result="sin"]',format(sin));setText(root,'[data-result="cos"]',format(cos));setText(root,'[data-result="tan"]',tangentDefined?format(tan):undefinedLabel);setText(root,'[data-result="coordinates"]',`(${format(cos,8)}, ${format(sin,8)})`);if(unit==="degrees"){setText(root,'[data-result="normalized"]',`${format(normalizeDegrees(raw),9)}°`)}else{setText(root,'[data-result="normalized"]',`${format(normalizeRadians(raw),9)} rad`)}const slider=root.querySelector(".trigonometry-slider");slider.value=String(Math.max(-360,Math.min(360,degrees)));updateCircle(root,radians,tan,undefinedLabel)};const setInverseResult=(root,name,radians,valid)=>{const outside=root.dataset.outofdomain;if(!valid){setText(root,`[data-result="${name}"]`,outside);setText(root,`[data-result="${name}rad"]`,"-");return}setText(root,`[data-result="${name}"]`,`${format(toDegrees(radians),10)}°`);setText(root,`[data-result="${name}rad"]`,`${format(radians,10)} rad`)};const calculateInverse=root=>{const input=root.querySelector(".trigonometry-inverse-value");const value=Number(input.value);if(!Number.isFinite(value)){["asin","acos","atan"].forEach(name=>{setText(root,`[data-result="${name}"]`,"-");setText(root,`[data-result="${name}rad"]`,"-")});return}const inUnitDomain=value>=-1&&value<=1;setInverseResult(root,"asin",inUnitDomain?Math.asin(value):NaN,inUnitDomain);setInverseResult(root,"acos",inUnitDomain?Math.acos(value):NaN,inUnitDomain);setInverseResult(root,"atan",Math.atan(value),true)};const setAngleFromDegrees=(root,degrees)=>{const input=root.querySelector(".trigonometry-angle");const unit=root.querySelector(".trigonometry-unit").value;input.value=unit==="degrees"?format(degrees,10):format(toRadians(degrees),10);calculateAngle(root)};const getSvgAngle=(svg,clientX,clientY)=>{const point=svg.createSVGPoint();point.x=clientX;point.y=clientY;const matrix=svg.getScreenCTM();if(!matrix){return null}const local=point.matrixTransform(matrix.inverse());const x=local.x-SVG_CENTER;const y=SVG_CENTER-local.y;return toDegrees(Math.atan2(y,x))};const bindCircle=root=>{const slider=root.querySelector(".trigonometry-slider");const svg=root.querySelector(".trigonometry-circle");const marker=root.querySelector(".trigonometry-point");let dragging=false;slider.addEventListener("input",()=>setAngleFromDegrees(root,Number(slider.value)));const updateFromPointer=event=>{const degrees=getSvgAngle(svg,event.clientX,event.clientY);if(degrees!==null){setAngleFromDegrees(root,degrees)}};marker.addEventListener("pointerdown",event=>{dragging=true;marker.setPointerCapture(event.pointerId);updateFromPointer(event)});marker.addEventListener("pointermove",event=>{if(dragging){updateFromPointer(event)}});marker.addEventListener("pointerup",event=>{dragging=false;if(marker.hasPointerCapture(event.pointerId)){marker.releasePointerCapture(event.pointerId)}});marker.addEventListener("pointercancel",()=>{dragging=false});marker.addEventListener("keydown",event=>{if(event.key!=="ArrowLeft"&&event.key!=="ArrowRight"&&event.key!=="ArrowUp"&&event.key!=="ArrowDown"){return}event.preventDefault();const current=Number(slider.value)||0;const delta=event.key==="ArrowLeft"||event.key==="ArrowDown"?-1:1;const next=Math.max(-360,Math.min(360,current+delta));slider.value=String(next);setAngleFromDegrees(root,next)})};const init=id=>{const root=document.getElementById(id);if(!root){return}const angle=root.querySelector(".trigonometry-angle");const unit=root.querySelector(".trigonometry-unit");const inverse=root.querySelector(".trigonometry-inverse-value");const clear=root.querySelector(".trigonometry-clear");angle.addEventListener("input",()=>calculateAngle(root));unit.addEventListener("change",()=>{const current=Number(angle.value);if(Number.isFinite(current)){angle.value=unit.value==="degrees"?format(toDegrees(current),10):format(toRadians(current),10)}calculateAngle(root)});inverse.addEventListener("input",()=>calculateInverse(root));clear.addEventListener("click",()=>{angle.value="0";unit.value="degrees";inverse.value="0";calculateAngle(root);calculateInverse(root);angle.focus()});bindCircle(root);calculateAngle(root);calculateInverse(root)};return{init:init}});